import{_t as e,it as t,n,rt as r}from"./chunks/framework.Ke88N3OB.js";var i=JSON.parse(`{"title":"Install and connect","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/packages/distant-horizons-support-pumpkin/docs/setup.md"},"headers":[],"relativePath":"packages/distant-horizons-support-pumpkin/docs/setup.md","filePath":"packages/distant-horizons-support-pumpkin/docs/setup.md","lastUpdated":1792508900000}`),a={name:`packages/distant-horizons-support-pumpkin/docs/setup.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="install-and-connect" tabindex="-1">Install and connect <a class="header-anchor" href="#install-and-connect" aria-label="Permalink to “Install and connect”">​</a></h1><h2 id="check-client-compatibility" tabindex="-1">Check client compatibility <a class="header-anchor" href="#check-client-compatibility" aria-label="Permalink to “Check client compatibility”">​</a></h2><p>Before you install the server plugin, check its README for the supported Distant Horizons release and protocol. Install the Distant Horizons mod on each Java Edition client that will connect; Bedrock players can&#39;t establish Distant Horizons sessions.</p><h2 id="install-the-server-plugin" tabindex="-1">Install the server plugin <a class="header-anchor" href="#install-the-server-plugin" aria-label="Permalink to “Install the server plugin”">​</a></h2><ol><li>Download the latest Distant Horizons Support release.</li><li>Copy <code>distant-horizons-support-pumpkin.wasm</code> into the Pumpkin server&#39;s <code>plugins/</code> folder.</li><li>Start or restart the server. On first load, the plugin requests the permissions listed in its README. Approve the request in the server console; hot reload can&#39;t display this prompt.</li><li>Once the plugin loads, it writes its settings file to <code>plugins/data/DistantHorizonsSupportPumpkin/config.toml</code>. Change the settings there if needed and restart the server.</li><li>Connect with a compatible Java client.</li></ol><p>The plugin README lists the available options, their defaults, and an example configuration. Distant Horizons Support serves terrain from chunks Pumpkin has loaded, along with terrain it captured earlier and cached. It can&#39;t load or generate distant chunks, so players see LODs for an area only after it has been loaded once. To prepare an area in advance, see <a href="./cache#capture-an-area-ahead-of-time">Manage the LOD cache</a>.</p><p>After connecting, run <code>/dhs status</code> to check that the client has a session, and <code>/dhs cache status</code> to see how much of the cache is in use.</p><p>PumpkinPIE is optional. Distant Horizons Support loads without it and reconnects automatically if PumpkinPIE becomes available later. The <code>dhs</code> expansion gives PumpkinPIE consumers access to session and cache values, without adding a required host plugin dependency. See the <a href="./placeholders">placeholder reference</a> for identifiers, values, and retry behavior.</p>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};